-- =========================================================
-- SAGASU - SCRIPT 11: P2P CHAT (UC35-39)
-- Run after the existing accounts/post/claim/item_receipt schema.
-- Creates chat storage and conversations for eligible APPROVED claims.
-- Existing posts, claims, claim evidence, account roles and read cursors
-- are preserved. No messages or attachments are generated by this script.
-- =========================================================

BEGIN;
SET LOCAL lock_timeout = '10s';
SET LOCAL search_path = public;

-- Fail atomically if a required base table is missing.
SELECT 'accounts'::regclass AS accounts_table,
       'post'::regclass AS post_table,
       'claim'::regclass AS claim_table,
       'item_receipt'::regclass AS item_receipt_table;

-- 1. One conversation per post and claimant, reused across claim retries.
-- The Finder is post.account_id; latest_claim_id points to the most recent
-- approved dossier for this pair. The application validates this relation.
-- OPEN/READ_ONLY is computed from the claim/post/account state, not stored.
CREATE TABLE IF NOT EXISTS chat_conversation (
    conversation_id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    post_id               BIGINT NOT NULL,
    claimant_id           BIGINT NOT NULL,
    latest_claim_id       BIGINT NOT NULL,
    last_message_sequence BIGINT NOT NULL DEFAULT 0,
    last_activity_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    version               BIGINT NOT NULL DEFAULT 0,

    CONSTRAINT chat_conversation_post_fk FOREIGN KEY (post_id)
        REFERENCES post(post_id) ON DELETE RESTRICT,
    CONSTRAINT chat_conversation_claimant_fk FOREIGN KEY (claimant_id)
        REFERENCES accounts(id) ON DELETE RESTRICT,
    CONSTRAINT chat_conversation_latest_claim_fk FOREIGN KEY (latest_claim_id)
        REFERENCES claim(claim_id) ON DELETE RESTRICT,
    CONSTRAINT uq_chat_conversation_post_claimant UNIQUE (post_id, claimant_id),
    CONSTRAINT chk_chat_conversation_sequence CHECK (last_message_sequence >= 0),
    CONSTRAINT chk_chat_conversation_version CHECK (version >= 0),
    CONSTRAINT chk_chat_conversation_updated_at CHECK (updated_at >= created_at),
    CONSTRAINT chk_chat_conversation_activity_at CHECK (last_activity_at >= created_at)
);

CREATE INDEX IF NOT EXISTS idx_chat_conversation_activity
    ON chat_conversation (last_activity_at DESC, conversation_id DESC);
CREATE INDEX IF NOT EXISTS idx_chat_conversation_claimant
    ON chat_conversation (claimant_id, conversation_id);
CREATE INDEX IF NOT EXISTS idx_chat_conversation_latest_claim
    ON chat_conversation (latest_claim_id);

-- 2. Two members with independent read watermarks.
-- participant_role describes the conversation relationship, not account.role.
-- PK + two allowed roles + UNIQUE role allow at most two distinct members.
-- The application creates both members in the approval transaction.
CREATE TABLE IF NOT EXISTS chat_participant (
    conversation_id   BIGINT NOT NULL,
    account_id        BIGINT NOT NULL,
    participant_role  VARCHAR(16) NOT NULL,
    last_read_sequence BIGINT NOT NULL DEFAULT 0,
    last_read_at      TIMESTAMPTZ,
    joined_at         TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chat_participant_pkey PRIMARY KEY (conversation_id, account_id),
    CONSTRAINT chat_participant_conversation_fk FOREIGN KEY (conversation_id)
        REFERENCES chat_conversation(conversation_id) ON DELETE RESTRICT,
    CONSTRAINT chat_participant_account_fk FOREIGN KEY (account_id)
        REFERENCES accounts(id) ON DELETE RESTRICT,
    CONSTRAINT uq_chat_participant_role UNIQUE (conversation_id, participant_role),
    CONSTRAINT chk_chat_participant_role CHECK
        (participant_role IN ('FINDER', 'CLAIMANT')),
    CONSTRAINT chk_chat_participant_read_sequence CHECK (last_read_sequence >= 0)
);

CREATE INDEX IF NOT EXISTS idx_chat_participant_account
    ON chat_participant (account_id, conversation_id);

-- 3. Durable messages, ordered within each conversation.
-- Allocate sequence_no while holding the chat_conversation row lock.
-- A global identity alone is not a reliable per-conversation read watermark.
CREATE TABLE IF NOT EXISTS chat_message (
    message_id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    conversation_id   BIGINT NOT NULL,
    sender_id         BIGINT NOT NULL,
    sequence_no       BIGINT NOT NULL,
    client_message_id UUID NOT NULL,
    message_type      VARCHAR(16) NOT NULL,
    body              TEXT,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chat_message_conversation_fk FOREIGN KEY (conversation_id)
        REFERENCES chat_conversation(conversation_id) ON DELETE RESTRICT,
    CONSTRAINT chat_message_sender_fk FOREIGN KEY (conversation_id, sender_id)
        REFERENCES chat_participant(conversation_id, account_id) ON DELETE RESTRICT,
    CONSTRAINT uq_chat_message_sequence UNIQUE (conversation_id, sequence_no),
    CONSTRAINT uq_chat_message_client_id UNIQUE
        (conversation_id, sender_id, client_message_id),
    CONSTRAINT chk_chat_message_sequence CHECK (sequence_no > 0),
    CONSTRAINT chk_chat_message_type CHECK
        (message_type IN ('TEXT', 'ATTACHMENT', 'MIXED')),
    CONSTRAINT chk_chat_message_body CHECK
        (body IS NULL OR char_length(btrim(body)) > 0),
    CONSTRAINT chk_chat_message_type_body CHECK ((
        (message_type IN ('TEXT', 'MIXED') AND body IS NOT NULL)
        OR (message_type = 'ATTACHMENT' AND body IS NULL)
    ) IS TRUE)
);

-- uq_chat_message_sequence already indexes (conversation_id, sequence_no)
-- for pagination, catch-up and unread queries. Do not duplicate that index.

-- 4. Private JPG/PNG/PDF objects belonging to a persisted message.
-- Configurable text/file/count/total-size limits are enforced by services;
-- SQL enforces basic validity without freezing those configurable limits.
CREATE TABLE IF NOT EXISTS chat_attachment (
    attachment_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    message_id    BIGINT NOT NULL,
    storage_key   TEXT NOT NULL,
    original_name VARCHAR(255),
    mime_type     VARCHAR(32) NOT NULL,
    size_bytes    BIGINT NOT NULL,
    content_hash  VARCHAR(64) NOT NULL,
    sort_order    SMALLINT NOT NULL,
    uploaded_at   TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chat_attachment_message_fk FOREIGN KEY (message_id)
        REFERENCES chat_message(message_id) ON DELETE RESTRICT,
    CONSTRAINT uq_chat_attachment_storage_key UNIQUE (storage_key),
    CONSTRAINT uq_chat_attachment_order UNIQUE (message_id, sort_order),
    CONSTRAINT chk_chat_attachment_key CHECK (char_length(btrim(storage_key)) > 0),
    CONSTRAINT chk_chat_attachment_mime CHECK
        (mime_type IN ('image/jpeg', 'image/png', 'application/pdf')),
    CONSTRAINT chk_chat_attachment_size CHECK (size_bytes > 0),
    CONSTRAINT chk_chat_attachment_hash CHECK (content_hash ~ '^[0-9a-fA-F]{64}$'),
    CONSTRAINT chk_chat_attachment_order CHECK (sort_order >= 0)
);

-- 5. Backfill conversations only for existing claims that can open P2P chat.
-- No approval is inferred from other statuses and no claim/post is updated.
-- Re-running does not replace a conversation, its claim pointer or counters.
INSERT INTO chat_conversation (post_id, claimant_id, latest_claim_id)
SELECT c.post_id, c.claimant_id, c.claim_id
FROM claim c
JOIN post p ON p.post_id = c.post_id
WHERE c.status = 'APPROVED'
  AND p.post_type = 'FOUND'
  AND p.custody_mode = 'P2P'
  AND p.moderation_status = 'VISIBLE'
  AND p.status = 'RESERVED'
  AND p.deleted_at IS NULL
  AND p.account_id <> c.claimant_id
  AND NOT EXISTS (
      SELECT 1 FROM item_receipt r WHERE r.post_id = p.post_id
  )
ON CONFLICT (post_id, claimant_id) DO NOTHING;

-- Add missing members without resetting existing read watermarks.
-- This also supports a safe rerun after the application has created chats.
INSERT INTO chat_participant
    (conversation_id, account_id, participant_role, joined_at)
SELECT conversation.conversation_id,
       member.account_id,
       member.participant_role,
       conversation.created_at
FROM chat_conversation conversation
JOIN post p ON p.post_id = conversation.post_id
CROSS JOIN LATERAL (
    VALUES (p.account_id, 'FINDER'), (conversation.claimant_id, 'CLAIMANT')
) AS member(account_id, participant_role)
ON CONFLICT (conversation_id, account_id) DO NOTHING;

COMMENT ON TABLE chat_conversation IS
    'UC35-39: One P2P conversation per post/claimant; reused across approved claim retries.';
COMMENT ON TABLE chat_participant IS
    'Two P2P members with monotonically increasing read watermarks in conversation-local sequence order.';
COMMENT ON TABLE chat_message IS
    'Immutable application messages; persist before publishing realtime events.';
COMMENT ON TABLE chat_attachment IS
    'Private R2 attachment metadata; never persist public or expiring signed URLs.';

COMMIT;

-- Application invariants for the next implementation step:
-- * Open/create on approval in the same transaction; reuse by post/claimant.
-- * Validate latest_claim_id belongs to this post and claimant, and members
--   are exactly post.account_id (Finder) and claimant_id (Claimant).
-- * Write only for APPROVED + FOUND/P2P/VISIBLE/RESERVED, not deleted and
--   not received by the office; check active accounts and membership.
-- * Keep history readable to participants when writing is no longer allowed.
-- * Lock post -> claim -> conversation when checking eligibility/sending.
-- * Advance last_message_sequence atomically with message/attachment writes.
-- * Validate attachment existence for ATTACHMENT/MIXED and absence for TEXT.
-- * Check configured text/file limits; validate actual file content.
-- * Derive sender from principal and verify attachment ownership before URLs.
-- * Move last_read_sequence forwards only, to a valid visible message sequence
--   in this conversation; unread excludes messages sent by that participant.
-- * Reuse client_message_id for retries; compare payloads before returning an
--   existing message, and clean up any unreferenced duplicate upload objects.
-- * Publish realtime events only after DB commit; catch up from DB on reconnect.
